/** The licences most reports and communities use, offered first. */
export const COMMON_ZENODO_LICENCES = ["cc-by-4.0", "cc-by-sa-4.0", "cc-by-nc-4.0", "cc-by-nd-4.0", "cc-by-nc-sa-4.0", "cc-by-nc-nd-4.0", "cc0-1.0"] as const;

const IDS = new Set(ZENODO_LICENCES.map(([id]) => id));

/** Whether Zenodo takes this licence id. */
export const isZenodoLicence = (id: string) => IDS.has(id);

/** A licence's title by its id, or the id itself for one Zenodo doesn't have. */
export const zenodoLicenceTitle = (id: string) => ZENODO_LICENCES.find(([known]) => known === id)?.[1] ?? id;

/** Where a record's licence terms are read: Zenodo's link for one of its licences, or the link a custom one was given. */
export const licenceTermsUrl = (licence: RecordLicence) => (licence.kind === "custom" ? licence.url : ZENODO_LICENCES.find(([known]) => known === licence.id)?.[2] || null);

// A Creative Commons link or short name, with its version and what follows it: a ported licence's jurisdiction
// ("/3.0/igo/", "CC BY 3.0 US"), or a word that names none ("/legalcode", "International").
const CC_URL = /creativecommons\.org\/licenses\/(by(?:-(?:nc|nd|sa))*)\/(\d\.\d)(?:\/([a-z.-]+))?/u;
// In a name, a jurisdiction is a country code or IGO; a common two-letter word after it names none ("CC BY 4.0 or later").
const CC_NAME = /\bcc[\s-]?(by(?:[\s-](?:nc|nd|sa))*)[\s-]+(\d\.\d)(?:[\s-](igo|(?!(?:an|as|by|in|is|it|of|on|or|to)\b)[a-z]{2})\b)?/u;
const CC_ZERO = /\bcc0\b|creativecommons\.org\/publicdomain\/zero\/1\.0/u;
// What can follow a version without naming a jurisdiction.
const NOT_A_PLACE = /^(?:legalcode.*|deed.*|international|unported|generic|licen[cs]e)$/u;
// Longest first, so a title holding another ("… 2.0 (no copyleft exception)" holds "… 2.0") finds the one it names.
const BY_TITLE = [...ZENODO_LICENCES].sort(([, a], [, b]) => b.length - a.length);

/** The Zenodo id of a Creative Commons licence, in its jurisdiction when it names one; null when Zenodo lacks it. */
function creativeCommons([, terms, version, after]: RegExpExecArray) {
	const place = after && !NOT_A_PLACE.test(after) ? after : null;
	const id = [`cc-${terms!.replace(/\s/gu, "-")}-${version}`, place].filter(Boolean).join("-");
	return isZenodoLicence(id) ? id : null;
}

/**
 * The licence a record's rights statement names, when it names one Zenodo takes: a Creative Commons licence by its
 * link or short name with its version ("CC BY-NC 4.0"), or any licence by its full title. Null when it names none, or
 * one without its version or in a jurisdiction Zenodo doesn't list, which is left for a person to pick, not guessed.
 */
export function licenceFromRights(rights: string | null | undefined): string | null {
	const text = rights?.toLowerCase().replace(/\s+/gu, " ") ?? "";
	if (!text) return null;
	if (CC_ZERO.test(text)) return "cc0-1.0";
	const cc = CC_URL.exec(text) ?? CC_NAME.exec(text);
	if (cc) return creativeCommons(cc);
	return BY_TITLE.find(([, title]) => text.includes(title.toLowerCase()))?.[0] ?? null;
}

/** A Creative Commons licence's short name, as people write it ("CC BY-NC 4.0"); null for other licences. */
export function licenceShortName(id: string) {
	if (id === "cc0-1.0") return "CC0 1.0";
	const cc = /^cc-(by(?:-(?:nc|nd|sa))*)-(\d\.\d)$/u.exec(id);
	return cc ? `CC ${cc[1]!.toUpperCase()} ${cc[2]}` : null;
}

/**
 * A record's licence: one of Zenodo's by its id, or another by its title and the web address of its terms. It goes
 * with the record's DOI to Zenodo and Crossref. Only records made in the community, which can get a DOI, hold one.
 */
export const recordLicenceSchema = z.discriminatedUnion("kind", [
	z.object({ kind: z.literal("zenodo"), id: z.string().refine(isZenodoLicence, "Zenodo doesn't take this licence") }).strict(),
	z
		.object({
			kind: z.literal("custom"),
			title: z.string().trim().max(200),
			url: z.string().trim().max(2048),
		})
		.strict(),
]);
export type RecordLicence = z.infer<typeof recordLicenceSchema>;

/** Whether a licence can go out with a DOI: one of Zenodo's, or another with both its title and a web link. */
export function licenceComplete(licence: RecordLicence | null | undefined): licence is RecordLicence {
	if (!licence) return false;
	return licence.kind === "zenodo" || (Boolean(licence.title) && /^https?:\/\//u.test(licence.url) && URL.canParse(licence.url));
}

/** A licence as one line: its short name where it has one, else its title. */
export function licenceLabel(licence: RecordLicence) {
	return licence.kind === "custom" ? licence.title : (licenceShortName(licence.id) ?? zenodoLicenceTitle(licence.id));
}

/** What a deposit sends for a licence: Zenodo's id, or the custom licence's title and link. */
export function publicationLicence(licence: RecordLicence): { license: string } | { customLicense: { title: string; url: string } } {
	return licence.kind === "zenodo" ? { license: licence.id } : { customLicense: { title: licence.title, url: licence.url } };
}
